insert into public.cruza_words (id, lang, cat, word, clue, clue2, explain, analogy) values
  ('ia-pt-token', 'pt', 'ia', 'Token', 'Pedacinho de texto (parte de uma palavra) que o modelo de IA lê e escreve', 'Em inglês, também é a ficha de fliperama; tem 5 letras', 'O modelo não lê letra por letra nem palavra por palavra: ele quebra o texto em pedaços chamados tokens. "Casamento" pode virar "casa" + "mento". O limite de memória e o custo de uma IA costumam ser contados nessa unidade.', 'É como montar frases com peças de Lego: em vez de letras soltas ou palavras inteiras, a IA usa pecinhas de tamanhos variados que se encaixam.'),
  ('ia-pt-vies', 'pt', 'ia', 'Viés', 'Tendência injusta que a IA herda dos dados com que aprendeu', 'Sinônimo de inclinação ou parcialidade; 4 letras', 'Se os exemplos usados para ensinar a IA mostram mais um grupo do que outro, ela passa a favorecer esse grupo nas respostas. Por isso é preciso revisar os dados e testar o sistema com públicos diversos.', 'É como aprender a cozinhar só com receitas da avó: você vira ótimo na comida dela, mas acha estranho tudo que foge daquele tempero.'),
  ('ia-pt-rede', 'pt', 'ia', 'Rede', 'Neural: estrutura de camadas de "neurônios" artificiais ligados entre si', 'Também é onde se deita na varanda ou o que o peixe evita; 4 letras', 'Uma rede neural é um programa com milhões de unidades simples ligadas em camadas. Cada ligação tem uma força ajustável; juntas, elas aprendem a reconhecer padrões como rostos, vozes ou frases.', 'É como um telefone sem fio gigante e bem treinado: cada pessoa passa a mensagem adiante com um ajuste, e no fim da fila sai uma resposta útil.'),
  ('ia-pt-robo', 'pt', 'ia', 'Robô', 'Máquina que age no mundo físico, às vezes guiada por IA', 'O aspirador que passeia sozinho pela sala é um; 4 letras', 'Um robô tem corpo: sensores para perceber o ambiente e motores para agir. Nem todo robô usa IA (muitos repetem movimentos fixos), e nem toda IA é um robô (a maioria vive só no computador).', 'É como a diferença entre cérebro e corpo: a IA pode ser o cérebro, mas o robô é o corpo que pega, anda e empurra.'),
  ('ia-pt-dados', 'pt', 'ia', 'Dados', 'Matéria-prima da IA: textos, fotos e números usados para ela aprender', 'Também são os cubinhos numerados de um jogo de tabuleiro; 5 letras', 'Uma IA aprende a partir de exemplos. Quanto mais variados, corretos e bem organizados forem esses exemplos, melhores tendem a ser as respostas. Informação ruim na entrada vira resposta ruim na saída.', 'É como os ingredientes de um bolo: a melhor receita do mundo não salva farinha estragada.'),
  ('ia-pt-peso', 'pt', 'ia', 'Peso', 'Número que define a força de cada ligação dentro de uma rede neural', 'O que a balança mede; 4 letras', 'Durante o aprendizado, a IA ajusta bilhões desses números um pouquinho de cada vez. Eles decidem quanto cada sinal importa. No fim, o "conhecimento" do modelo está guardado nesse conjunto de valores.', 'É como a mesa de som de um show: cada botão aumenta ou abaixa um instrumento, e o som final depende de como todos foram regulados.'),
  ('ia-pt-prompt', 'pt', 'ia', 'Prompt', 'O pedido ou instrução que você escreve para uma IA responder', 'Termo em inglês para a "deixa" dada ao ator no teatro; 6 letras', 'É o texto de entrada: a pergunta, a tarefa e o contexto que você dá à IA. Pedidos claros, com objetivo, exemplos e formato desejado, costumam gerar respostas bem melhores.', 'É como pedir um prato no restaurante: "algo gostoso" pode vir qualquer coisa; "massa sem glúten, pouco sal" chega muito mais perto do que você quer.'),
  ('ia-pt-harness', 'pt', 'ia', 'Harness', 'A estrutura que liga um modelo de IA a ferramentas, memória e regras', 'Em inglês, também é o arreio que prende o cavalo à carroça', 'Um modelo de IA sozinho só conversa. O harness é o programa em volta dele que dá acesso a ferramentas (buscar na web, ler arquivos), guarda o contexto e define os limites do que ele pode fazer.', 'É como o arreio de um cavalo: o cavalo tem a força, mas é o arreio que liga essa força à carroça e deixa você guiá-la na direção certa.'),
  ('ia-pt-agente', 'pt', 'ia', 'Agente', 'IA que planeja e executa várias etapas sozinha, usando ferramentas', 'Também é o espião dos filmes, como o 007; 6 letras', 'Em vez de só responder uma pergunta, ele recebe um objetivo, divide em passos, usa ferramentas (busca, planilha, código), confere o resultado e segue até terminar. Por isso precisa de limites e supervisão.', 'É como a diferença entre perguntar o caminho e contratar um motorista: um só informa, o outro dirige até lá, desviando do trânsito no percurso.'),
  ('ia-pt-modelo', 'pt', 'ia', 'Modelo', 'O "cérebro" treinado de uma IA, resultado de aprender com muitos exemplos', 'Também é quem desfila na passarela; 6 letras', 'É o arquivo que sai do treinamento: uma enorme coleção de números ajustados que transforma uma entrada (texto, imagem) em uma saída. Chatbots, tradutores e geradores de imagem rodam sobre um deles.', 'É como um motor pronto: foi projetado e testado na fábrica, e agora pode ser colocado em carros diferentes para rodar.'),
  ('ia-pt-contexto', 'pt', 'ia', 'Contexto', 'Tudo o que a IA consegue "ter em mente" de uma vez durante a conversa', 'Fora dele, uma frase pode mudar de sentido; 8 letras', 'A IA só considera o que cabe na sua janela de entrada: suas mensagens, as respostas dela e documentos enviados. O que sai dessa janela ela simplesmente não enxerga mais, a menos que seja repetido.', 'É como a lousa da sala de aula: dá para usar tudo que está escrito nela, mas quando enche, alguém precisa apagar uma parte para continuar.'),
  ('ia-pt-chatbot', 'pt', 'ia', 'Chatbot', 'Programa que conversa com você por mensagens escritas', 'Junta "bate-papo" e "robô" em inglês; 7 letras', 'É a interface de conversa: você escreve, ele responde. Os antigos seguiam roteiros fixos; os atuais usam modelos de linguagem e conseguem lidar com perguntas que ninguém previu.', 'É como o atendente do balcão de informações: você chega com dúvidas do seu jeito e ele tenta entender e responder na hora.'),
  ('ia-pt-treino', 'pt', 'ia', 'Treino', 'Fase em que a IA aprende ajustando-se a milhões de exemplos', 'O que o atleta faz antes do jogo; 6 letras', 'O sistema tenta prever a resposta, compara com a certa, mede o erro e se corrige um pouquinho. Repetido bilhões de vezes, esse ciclo transforma números aleatórios em um modelo útil. É caro e demorado.', 'É como aprender a cobrar pênaltis: chutar, ver onde a bola foi, corrigir o pé e repetir até acertar o canto quase sempre.'),
  ('ia-pt-alucinacao', 'pt', 'ia', 'Alucinação', 'Quando a IA inventa um fato falso e o apresenta com toda a confiança', 'Na medicina, é ver ou ouvir algo que não existe; 10 letras', 'O modelo gera o texto mais provável, não o mais verdadeiro. Às vezes isso produz citações, datas ou fontes inventadas que soam corretas. Por isso vale conferir informações importantes em fontes confiáveis.', 'É como um aluno que não estudou e, na prova oral, responde com segurança algo que soa certo, mas que ele inventou na hora.'),
  ('ia-pt-inferencia', 'pt', 'ia', 'Inferência', 'Momento em que um modelo já treinado é usado para responder', 'Também é tirar uma conclusão a partir de pistas; 10 letras', 'Depois do treino, o modelo não aprende mais a cada pergunta: ele só aplica o que já sabe para gerar uma resposta. Cada vez que você manda uma mensagem a um chatbot, acontece uma dessas.', 'É como o dia da prova depois de meses de estudo: você não aprende matéria nova ali, só usa o que já tem na cabeça.'),
  ('ia-pt-algoritmo', 'pt', 'ia', 'Algoritmo', 'Sequência de passos bem definidos para resolver um problema', 'Nas redes sociais, é o que escolhe o que aparece no seu feed; 9 letras', 'É um conjunto de instruções que, seguidas em ordem, levam a um resultado. Todo programa usa vários. Na IA, há algoritmos que ensinam o modelo e outros que decidem como ele responde.', 'É como uma receita de bolo: misture isto, depois aquilo, asse por 40 minutos. Seguindo os passos, qualquer um chega ao mesmo resultado.'),
  ('ia-pt-generativa', 'pt', 'ia', 'Generativa', 'Tipo de IA que cria textos, imagens, músicas ou vídeos novos', 'Vem do verbo "gerar"; 10 letras', 'Ao contrário da IA que só classifica (isto é spam ou não?), esse tipo produz conteúdo inédito a partir dos padrões que aprendeu. Ela combina o que viu de formas novas, mas não copia um exemplo único.', 'É como um músico que ouviu milhares de sambas: ele não repete nenhum, mas compõe um samba novo com aquele jeito e aquela batida.'),
  ('ia-pt-aprendizado', 'pt', 'ia', 'Aprendizado', 'De máquina: quando o computador descobre regras sozinho a partir de exemplos', 'O que acontece na escola; 11 letras', 'Em vez de um programador escrever cada regra, o sistema recebe muitos exemplos (fotos de gatos e de cães, por exemplo) e encontra sozinho os padrões que separam um do outro.', 'É como uma criança que aprende o que é "cachorro" vendo muitos cachorros, sem ninguém explicar a definição: ela simplesmente pega o padrão.'),
  ('ia-en-token', 'en', 'ia', 'Token', 'A chunk of text, often part of a word, that a language model reads and writes', 'Also an arcade coin; 5 letters', 'Models do not read letter by letter or word by word: they split text into pieces. "Unbelievable" might become "un" + "believ" + "able". Context limits and usage costs are usually counted in these units.', 'It''s like building sentences from Lego bricks: not single letters, not whole words, but pieces of various sizes that snap together.'),
  ('ia-en-bias', 'en', 'ia', 'Bias', 'Unfair slant an AI picks up from lopsided training examples', 'Synonym of prejudice or partiality; 4 letters', 'If the examples used to teach an AI over-represent one group, its answers will lean that way too. Checking the data and testing the system with diverse users helps catch and reduce it.', 'Think of a referee who only ever watched one team play: without meaning to, they read every close call through that team''s eyes.'),
  ('ia-en-agent', 'en', 'ia', 'Agent', 'AI that plans and carries out multi-step tasks on its own, using tools', 'James Bond is a famous secret one; 5 letters', 'Instead of answering one question, it takes a goal, breaks it into steps, uses tools like search or code, checks results and keeps going until done. That autonomy is why it needs clear limits and oversight.', 'It''s like the difference between asking for directions and hiring a driver: one just tells you the way, the other gets you there and reroutes around traffic.'),
  ('ia-en-model', 'en', 'ia', 'Model', 'The trained "brain" of an AI system, built by learning from huge numbers of examples', 'Also someone who walks the runway; 5 letters', 'It is the file that comes out of training: a vast set of tuned numbers that turns an input (text, image) into an output. Chatbots, translators and image generators all run on one.', 'Think of a finished engine: designed and tested at the factory, it can now be dropped into different cars to make them go.'),
  ('ia-en-layer', 'en', 'ia', 'Layer', 'One level of artificial neurons stacked inside a neural network', 'A cake or an onion has several; 5 letters', 'Neural networks pass information through stacked levels. Early ones spot simple things like edges or letter shapes; later ones combine them into faces or meanings. "Deep" learning just means many of these.', 'It''s like an assembly line: the first station cuts the wood, the next sands it, the next paints it, and a finished chair rolls out at the end.'),
  ('ia-en-robot', 'en', 'ia', 'Robot', 'Machine that senses and acts in the physical world, sometimes guided by AI', 'A self-driving vacuum cleaner is one; 5 letters', 'It has a body: sensors to perceive its surroundings and motors to act. Not every one uses AI (many repeat fixed motions), and most AI never gets a body, living only on computers.', 'Think of brain and body: AI can be the brain, but this is the body that grabs, walks and pushes.'),
  ('ia-en-prompt', 'en', 'ia', 'Prompt', 'The request or instructions you type to get an AI to respond', 'In theatre, it is the cue whispered to an actor; 6 letters', 'It is the input text: your question, the task and any background. Clear requests with a goal, examples and the format you want usually get much better answers.', 'It''s like ordering at a restaurant: "something nice" could bring anything; "spicy noodles, no peanuts" gets you much closer to what you want.'),
  ('ia-en-harness', 'en', 'ia', 'Harness', 'The software around an AI model that connects it to tools, memory and rules', 'Also the straps that hitch a horse to a cart; 7 letters', 'A model on its own can only chat. This surrounding program gives it tools (web search, reading files), manages what it remembers and sets the limits on what it is allowed to do.', 'Think of a horse''s tack: the horse has the power, but the straps connect that power to the cart and let you steer it.'),
  ('ia-en-context', 'en', 'ia', 'Context', 'Everything an AI can keep "in mind" at once during a conversation', 'Quotes taken out of it can mislead; 7 letters', 'The model only considers what fits in its input window: your messages, its replies and any documents you share. Anything that falls out of that window it simply cannot see anymore unless repeated.', 'It''s like a classroom whiteboard: you can use everything written on it, but once it fills up, something has to be erased to keep going.'),
  ('ia-en-weights', 'en', 'ia', 'Weights', 'The billions of tuned numbers inside a neural network that store what it learned', 'What you lift at the gym; 7 letters', 'Each one sets how strongly one artificial neuron influences the next. Training nudges them bit by bit until the outputs improve. When people "release a model", these numbers are mostly what they share.', 'Think of a mixing desk at a concert: each slider turns one instrument up or down, and the final sound depends on how every slider is set.'),
  ('ia-en-chatbot', 'en', 'ia', 'Chatbot', 'Program you talk to by typing messages back and forth', 'A blend of "talk" and "robot" in English slang; 7 letters', 'It is a conversational interface: you write, it replies. Older ones followed fixed scripts; modern ones run on language models and can handle questions nobody planned for.', 'It''s like the person at an information desk: you arrive with questions phrased your own way and they try to understand and answer on the spot.'),
  ('ia-en-dataset', 'en', 'ia', 'Dataset', 'Organized collection of examples used to teach or test an AI', 'Think spreadsheet of labeled photos or texts; 7 letters', 'It might be millions of sentences, photos with labels, or sensor readings. Its quality shapes the AI: missing, wrong or skewed examples lead to gaps and errors in what the system learns.', 'It''s like the textbook a student studies from: if chapters are missing or full of mistakes, even a brilliant student learns the wrong things.'),
  ('ia-en-training', 'en', 'ia', 'Training', 'Phase where an AI learns by adjusting itself to millions of examples', 'What athletes do before a big game; 8 letters', 'The system guesses an answer, compares it with the right one, measures the error and corrects itself slightly. Repeated billions of times, that loop turns random numbers into a useful model. It is slow and costly.', 'It''s like practicing free throws: shoot, see where the ball went, adjust your arm, and repeat until it drops in nearly every time.'),
  ('ia-en-inference', 'en', 'ia', 'Inference', 'When an already-trained model is put to work answering requests', 'Also means drawing a conclusion from clues, like a detective; 9 letters', 'After training, the model does not learn from each question; it just applies what it already knows to produce an answer. Every message you send a chatbot triggers one of these.', 'It''s like exam day after months of study: you are not learning new material in the room, just using what is already in your head.'),
  ('ia-en-algorithm', 'en', 'ia', 'Algorithm', 'A precise, step-by-step procedure for solving a problem', 'On social media, it decides what shows up in your feed; 9 letters', 'It is a set of instructions that, followed in order, reliably produce a result. Every program uses many. In AI, some of them teach the model and others decide how it generates answers.', 'It''s like a recipe: mix this, then that, bake for 40 minutes. Follow the steps and anyone gets the same cake.'),
  ('ia-en-guardrail', 'en', 'ia', 'Guardrail', 'Safety rule or filter that keeps an AI from producing harmful output', 'Also the metal barrier along a mountain road; 9 letters', 'These are checks built around or into an AI system: blocking dangerous instructions, protecting private data, or asking a human before risky actions. They limit harm without stopping normal use.', 'Think of the barrier on a winding road: you drive freely, but it stops you from going over the edge if you swerve.'),
  ('ia-en-embedding', 'en', 'ia', 'Embedding', 'List of numbers that places a word or image on a "map of meaning"', 'Lets AI find that "puppy" sits close to "dog"; 9 letters', 'AI turns words, sentences or pictures into long lists of numbers, like coordinates. Similar meanings end up close together, which lets search tools find related content even without matching words.', 'It''s like a supermarket layout: pasta sits near the sauces and far from the soap, so knowing where one thing is tells you where to find its neighbors.'),
  ('ia-en-overfitting', 'en', 'ia', 'Overfitting', 'When an AI memorizes its practice examples and then fails on new ones', 'Like cramming the answer key instead of learning; 11 letters', 'The model gets so tuned to its training examples, quirks and noise included, that it scores brilliantly on them but poorly on anything new. Testing on unseen data is how developers catch it.', 'It''s like a student who memorizes last year''s test answers: perfect score on that exact test, lost the moment the questions change.'),
  ('atualidades-pt-voto', 'pt', 'atualidades', 'Voto', 'Escolha que o eleitor registra na urna', 'Quatro letras; no Brasil, é obrigatório para a maioria dos adultos', 'É a forma de cada cidadão dizer quem deve governar ou qual proposta prefere. Ser secreto protege a pessoa de pressão: ninguém sabe em quem ela escolheu.', 'É como a votação da turma para escolher o passeio da escola: cada aluno tem uma voz e a maioria decide o destino de todos.'),
  ('atualidades-pt-censo', 'pt', 'atualidades', 'Censo', 'Contagem geral da população feita pelo IBGE, de casa em casa', 'Pesquisa que tenta ouvir todos os moradores do país, cerca de uma vez por década', 'É a pesquisa que conta todos os habitantes e registra como vivem: idade, moradia, renda, escolaridade. Esses dados orientam onde construir escolas, postos de saúde e linhas de ônibus.', 'É como fazer o inventário da despensa antes da feira: sem saber o que e quanto você tem, não dá para planejar o que comprar.'),
  ('atualidades-pt-seca', 'pt', 'atualidades', 'Seca', 'Longo período com chuva bem abaixo do normal numa região', 'O contrário de enchente; castiga o sertão nordestino', 'Acontece quando chove muito menos que o esperado por meses ou anos. Rios e reservatórios baixam, a lavoura sofre e pode faltar água e até energia, já que muitas usinas dependem de rios.', 'É como uma conta bancária em que só saem pagamentos e não entra salário: o saldo vai sumindo até não sobrar nada para as despesas básicas.'),
  ('atualidades-pt-greve', 'pt', 'atualidades', 'Greve', 'Parada coletiva do trabalho para pressionar por direitos ou salários', 'Cinco letras; é um direito garantido pela Constituição brasileira', 'Trabalhadores combinam parar juntos para negociar melhores condições. Funciona porque a falta do serviço mostra o quanto ele importa; serviços essenciais precisam manter um mínimo funcionando.', 'É como quando todos da casa param de lavar a louça ao mesmo tempo: a pia cheia deixa claro que a divisão de tarefas precisa ser conversada.'),
  ('atualidades-pt-meme', 'pt', 'atualidades', 'Meme', 'Imagem ou piada que se espalha pela internet e ganha versões novas', 'Quatro letras; muitas vezes uma foto engraçada com uma frase por cima', 'É uma ideia, imagem ou vídeo copiado e modificado por muita gente nas redes. Pode ser só humor, mas também é usado para propaganda política, porque é curto, fácil de compartilhar e mexe com emoções.', 'É como uma receita de bolo passada de família em família: cada um troca um ingrediente, mas todo mundo reconhece de onde veio.'),
  ('atualidades-pt-asilo', 'pt', 'atualidades', 'Asilo', 'Proteção que um país dá a quem é perseguido no país de origem', 'Cinco letras; vem antes de "político" quando um opositor foge do seu país', 'É o acolhimento oficial de alguém que corre risco em casa por suas ideias, religião ou atuação política. O país que acolhe se compromete a não mandá-lo de volta para o perigo.', 'É como a casa de um vizinho que abre a porta para quem está sendo ameaçado na rua: ali dentro a pessoa fica protegida.'),
  ('atualidades-pt-tarifa', 'pt', 'atualidades', 'Tarifa', 'Imposto cobrado sobre um produto quando ele entra no país', 'Seis letras; também é o preço da passagem de ônibus', 'É uma taxa sobre importações. Encarece o produto estrangeiro para proteger quem produz no país, mas pode subir os preços para o consumidor e provocar retaliação de outros países.', 'É como um pedágio na entrada da cidade só para caminhões de fora: o produto local fica mais competitivo, mas quem compra acaba pagando parte do pedágio.'),
  ('atualidades-pt-sancao', 'pt', 'atualidades', 'Sanção', 'Punição econômica ou política que países aplicam a outro governo', 'Seis letras; também é quando o presidente aprova uma lei', 'São medidas como congelar bens, proibir comércio ou barrar viagens para pressionar um governo a mudar de conduta sem usar armas. Às vezes atingem também a população comum.', 'É como um grupo de amigos que para de convidar alguém que vive furando os combinados: ninguém briga, mas a exclusão pesa e pressiona por mudança.'),
  ('atualidades-pt-enchente', 'pt', 'atualidades', 'Enchente', 'Quando um rio transborda e a água invade ruas e casas', 'Sinônimo de inundação; o contrário da seca', 'Ocorre quando chove mais do que o solo e os rios conseguem escoar. Cidades com muito asfalto e pouco verde sofrem mais, porque a água não infiltra e corre toda de uma vez.', 'É como abrir a torneira toda numa pia com o ralo meio entupido: a água chega mais rápido do que consegue sair e transborda.'),
  ('atualidades-pt-deepfake', 'pt', 'atualidades', 'Deepfake', 'Vídeo ou áudio falso, gerado por computador, que imita uma pessoa real', 'Termo em inglês; põe na boca de alguém palavras que ele nunca disse', 'É uma montagem tão realista que parece mesmo a pessoa falando ou agindo. Pode servir para golpes e boatos; vale desconfiar de vídeos chocantes e checar em fontes confiáveis antes de compartilhar.', 'É como uma máscara de cinema perfeita: de longe você jura que é o ator, mas é outra pessoa por trás, dizendo o que quiser.'),
  ('atualidades-pt-embargo', 'pt', 'atualidades', 'Embargo', 'Proibição de comerciar com um país, imposta por outro', 'Sete letras; na Justiça, também é o recurso "de declaração"', 'É um tipo forte de sanção: um país (ou grupo de países) proíbe vender, comprar ou transportar mercadorias para outro, total ou parcialmente, como forma de pressão.', 'É como um condomínio que proíbe as entregas para um apartamento: os moradores ficam sem receber o que precisam até resolver o problema.'),
  ('atualidades-pt-cupula', 'pt', 'atualidades', 'Cúpula', 'Reunião de chefes de Estado para discutir grandes temas', 'Seis letras; também é o topo arredondado de uma igreja', 'É um encontro entre os líderes máximos de vários países para negociar acordos sobre clima, comércio ou segurança. O nome vem da ideia de reunir quem está no topo.', 'É como a reunião dos chefes de família antes de uma grande festa: cada um traz seus interesses, e só sai acordo se todos cederem um pouco.'),
  ('atualidades-pt-refugiado', 'pt', 'atualidades', 'Refugiado', 'Quem foge do país por guerra ou perseguição e não pode voltar', 'Pessoa protegida por uma convenção da ONU de 1951', 'É quem precisou sair do próprio país por medo de perseguição ou por conflitos graves. Diferente de quem migra por escolha, essa pessoa não pode voltar com segurança, e a lei internacional a protege.', 'É como sair correndo de casa durante um incêndio: você não escolheu mudar, e precisa que alguém te acolha enquanto não há para onde voltar.'),
  ('atualidades-pt-plebiscito', 'pt', 'atualidades', 'Plebiscito', 'Consulta popular feita ANTES de uma lei ou decisão ser criada', 'Em 1993 os brasileiros escolheram assim entre república e monarquia', 'É quando o governo pergunta diretamente ao povo, por voto, se uma ideia deve ir em frente. O primo dele, o referendo, acontece depois: o povo confirma ou rejeita algo já aprovado.', 'É como a família votar se vai viajar para a praia ou para o campo antes de reservar qualquer coisa: a decisão vem primeiro, o plano depois.'),
  ('atualidades-pt-polarizacao', 'pt', 'atualidades', 'Polarização', 'Quando a sociedade se divide em dois lados que mal conversam', 'Vem de "polo": como norte e sul de um ímã, cada vez mais distantes', 'É o afastamento crescente entre grupos políticos, a ponto de cada lado ver o outro como inimigo. O meio-termo encolhe e fica difícil negociar até problemas simples.', 'É como uma torcida de clássico em que ninguém mais assiste ao jogo: só importa vaiar o outro lado, mesmo quando ele faz uma boa jogada.'),
  ('atualidades-pt-democracia', 'pt', 'atualidades', 'Democracia', 'Regime em que o povo escolhe seus governantes e pode trocá-los', 'Do grego: "governo do povo"; nasceu em Atenas', 'Vai além de votar: inclui eleições livres, imprensa livre, Justiça independente e respeito às minorias. O poder é dividido para que ninguém mande sozinho.', 'É como um condomínio com assembleia: os moradores elegem o síndico, fiscalizam as contas e podem trocá-lo na próxima reunião.'),
  ('atualidades-pt-urbanizacao', 'pt', 'atualidades', 'Urbanização', 'Movimento de pessoas do campo para as cidades, que crescem', 'Hoje a maior parte dos brasileiros mora em áreas assim', 'É o processo de as cidades concentrarem cada vez mais gente. Traz empregos e serviços, mas, sem planejamento, gera trânsito, moradias precárias e pressão sobre água e esgoto.', 'É como uma festa em que todo mundo vai para a cozinha: ali está a comida e a conversa, mas, se ninguém organizar, fica apertado e bagunçado.'),
  ('atualidades-pt-diplomacia', 'pt', 'atualidades', 'Diplomacia', 'Arte de negociar entre países para evitar conflitos e fazer acordos', 'É o trabalho de embaixadores e do Itamaraty', 'É o conjunto de conversas, tratados e gestos entre governos para resolver diferenças sem guerra. No dia a dia, a palavra também significa tato ao lidar com pessoas.', 'É como a mãe que media a briga dos irmãos pelo controle remoto: ouve os dois lados e encontra um acordo antes que alguém saia chorando.'),
  ('atualidades-en-veto', 'en', 'atualidades', 'Veto', 'The power to block a law or decision, even if others approved it', 'Four letters; Latin for "I forbid"', 'A leader or body can reject a decision passed by others. Presidents can often refuse to sign bills, and some UN Security Council members can block resolutions alone.', 'It''s like a parent who can cancel the sleepover the kids all voted for: one "no" outweighs the majority.'),
  ('atualidades-en-smog', 'en', 'atualidades', 'Smog', 'Brownish haze of air pollution hanging over a big city', 'Four letters; a blend of "smoke" and "fog"', 'It forms when exhaust and factory emissions mix with sunlight and still air. It irritates lungs and eyes, which is why some cities limit traffic on bad-air days.', 'Think of a kitchen with no window open after frying: the smoke lingers, and everyone in the room ends up breathing it.'),
  ('atualidades-en-lobby', 'en', 'atualidades', 'Lobby', 'Organized effort to influence lawmakers on behalf of a group', 'Five letters; also the entrance hall of a hotel', 'Companies, unions and causes hire people to persuade politicians to vote their way. It can bring useful expertise, but needs transparency so money doesn''t drown out ordinary voices.', 'It''s like a kid who keeps whispering to the teacher about which field trip to pick: the loudest, most persistent voice can sway the choice.'),
  ('atualidades-en-exile', 'en', 'atualidades', 'Exile', 'Being forced to live away from your home country', 'Five letters; Napoleon was sent to Elba and later Saint Helena', 'It happens when someone is banished or must flee to stay safe, often for political reasons. Many writers and activists have kept speaking out from abroad while unable to return.', 'Think of being sent out of the classroom for good: you can still hear the lesson through the door, but you can''t walk back in.'),
  ('atualidades-en-troll', 'en', 'atualidades', 'Troll', 'Online user who posts to provoke anger and derail conversations', 'Five letters; also a cave-dwelling creature in fairy tales', 'They post insults or inflammatory claims to get a reaction. Some are bored individuals; others are organized campaigns trying to sow division. Not replying usually starves them.', 'It''s like someone who tosses a firecracker into a quiet picnic just to watch everyone jump.'),
  ('atualidades-en-poll', 'en', 'atualidades', 'Poll', 'Survey of a sample of people to estimate public opinion', 'Four letters; often comes with a "margin of error"', 'Pollsters ask a carefully chosen sample instead of everyone. If the sample mirrors the population, results are close to reality, within a margin of error.', 'It''s like tasting one spoonful of soup to judge the whole pot: it works only if you stirred it well first.'),
  ('atualidades-en-tariff', 'en', 'atualidades', 'Tariff', 'Tax charged on imported goods at the border', 'Six letters; trade wars are fought with these', 'It makes foreign products pricier to protect local producers or pressure another country. The cost is often passed on to shoppers, and trading partners may respond with their own.', 'Think of a cover charge only for guests from other neighborhoods: locals get in cheaper, but the party may end up smaller and pricier.'),
  ('atualidades-en-sanction', 'en', 'atualidades', 'Sanction', 'Penalty, like frozen assets or trade bans, imposed on a country', 'Eight letters; a diplomatic punishment short of war', 'Governments use them to pressure others to change behavior without fighting. They can target leaders, banks or whole sectors, and sometimes hurt ordinary citizens too.', 'It''s like grounding a teenager: no allowance, no car keys, until the rules are respected again.'),
  ('atualidades-en-boycott', 'en', 'atualidades', 'Boycott', 'Refusing to buy from or deal with someone as a form of protest', 'Named after a 19th-century Irish land agent, Captain Charles ___', 'Consumers or groups stop buying products, attending events or working with a company to push for change. Its strength comes from many people acting together.', 'Think of a whole class refusing to buy from the cafeteria until it stops selling stale bread.'),
  ('atualidades-en-drought', 'en', 'atualidades', 'Drought', 'Long stretch of unusually low rainfall that dries up land and rivers', 'Seven letters; the opposite of a flood', 'When rain stays far below normal for months, soil dries, crops fail and reservoirs drop. A warming climate can make some regions'' dry spells longer and more intense.', 'It''s like a savings account with only withdrawals: each week the balance shrinks until there''s nothing left for essentials.'),
  ('atualidades-en-asylum', 'en', 'atualidades', 'Asylum', 'Legal protection a country grants to someone fleeing persecution', 'Six letters; people "seek" it at the border', 'A person who fears persecution at home can ask another country for protection. If granted, they can stay legally and must not be sent back to danger.', 'Think of a neighbor who opens their door to someone being chased down the street: inside, they''re safe.'),
  ('atualidades-en-summit', 'en', 'atualidades', 'Summit', 'High-level meeting where heads of state negotiate face to face', 'Six letters; also the top of a mountain', 'Leaders gather to discuss big issues like climate, trade or security. Much of the real work is done beforehand by diplomats, so the meeting can seal the deal.', 'It''s like the final meeting of team captains after coaches spent weeks prepping: the handshake is quick, the groundwork was long.'),
  ('atualidades-en-referendum', 'en', 'atualidades', 'Referendum', 'Direct public vote on a single question or law', 'Ten letters; voters answer "yes" or "no" on an issue', 'Instead of leaving a decision to elected representatives, the whole electorate votes on it directly. It is often used for constitutional changes or big national choices.', 'Think of a family skipping the parents-only decision and letting everyone vote on whether to get a dog.'),
  ('atualidades-en-propaganda', 'en', 'atualidades', 'Propaganda', 'Messaging designed to sway opinion, often through emotion or distortion', 'Ten letters; wartime posters were classic examples', 'It spreads a one-sided message to win support for a cause, government or leader. It favors repetition and emotion over facts, so asking "who benefits?" helps spot it.', 'It''s like a menu photo of a burger: perfectly styled to make you want it, rarely what actually arrives.'),
  ('atualidades-en-sovereignty', 'en', 'atualidades', 'Sovereignty', 'A state''s full authority to govern itself without outside control', 'Eleven letters; self-rule, the opposite of being a colony', 'It means a country makes its own laws and decisions within its borders. Joining treaties or alliances can mean sharing some of it in exchange for cooperation.', 'Think of having your own apartment: you set the house rules, and neighbors can''t walk in and rearrange the furniture.'),
  ('atualidades-en-migration', 'en', 'atualidades', 'Migration', 'Movement of people from one place to live in another', 'Nine letters; birds do it seasonally, too', 'People move for work, family, safety or climate reasons, within or across countries. It reshapes economies and cultures in both the places they leave and where they settle.', 'It''s like players transferring between teams: each move changes both squads, bringing new skills to one and leaving a gap in the other.'),
  ('atualidades-en-gerrymander', 'en', 'atualidades', 'Gerrymander', 'To redraw voting districts to favor one party', 'Named after a 19th-century governor and a salamander-shaped district', 'By packing opponents into a few districts or splitting them across many, map-drawers can win more seats than their share of votes. Independent commissions are one remedy.', 'It''s like picking teams for a match by putting all the strong players on your side: the game is decided before it starts.'),
  ('atualidades-en-clickbait', 'en', 'atualidades', 'Clickbait', 'Sensational headline designed mainly to lure you into clicking', 'Nine letters; "You won''t believe what happened next!"', 'Websites earn money from views, so some headlines exaggerate or hide the point to spark curiosity. The article often fails to deliver, and the habit can spread misleading stories.', 'Think of a shop window with a giant "FREE" sign: you walk in, and the free thing turns out to be a tiny sticker.'),
  ('ciencia-pt-atomo', 'pt', 'ciencia', 'Átomo', 'Menor pedaço de um elemento químico que ainda guarda as propriedades dele', 'Tem núcleo de prótons e nêutrons, com elétrons em volta (5 letras)', 'Tudo o que existe é feito deles. No centro fica um núcleo minúsculo, com prótons e nêutrons, e ao redor giram os elétrons. O número de prótons define o elemento: 1 é hidrogênio, 6 é carbono, 8 é oxigênio.', 'É como as peças de um brinquedo de montar: com poucos tipos de peça dá para construir de tudo, de uma casinha a um castelo. A água, o ar e você são montagens diferentes das mesmas peças.'),
  ('ciencia-pt-gene', 'pt', 'ciencia', 'Gene', 'Trecho do DNA que traz a instrução para fabricar uma proteína', 'Herdamos metade do pai e metade da mãe; define a cor dos olhos (4 letras)', 'O DNA é uma molécula longa, e cada trecho com uma "receita" específica é uma dessas unidades. A célula lê a receita e monta a proteína correspondente, que faz algum trabalho no corpo.', 'É como uma receita dentro de um enorme livro de culinária da família: o livro é o DNA, cada receita ensina a preparar um prato, e esse prato é uma proteína.'),
  ('ciencia-pt-chip', 'pt', 'ciencia', 'Chip', 'Plaquinha de silício com bilhões de minúsculos interruptores elétricos', 'É o "cérebro" do celular e do computador; também é o cartão da operadora', 'É um circuito integrado: em uma lâmina de silício do tamanho de uma unha cabem bilhões de transistores, interruptores que ligam e desligam a corrente. Combinados, fazem contas e guardam dados.', 'É como uma cidade vista do alto, com ruas e semáforos: a eletricidade é o trânsito, e cada transistor é um semáforo que deixa passar ou bloqueia.'),
  ('ciencia-pt-pixel', 'pt', 'ciencia', 'Pixel', 'O menor pontinho colorido que forma uma imagem numa tela', 'Quanto mais deles numa tela, mais nítida a imagem (5 letras)', 'Telas e fotos digitais são grades de pontos, cada um com uma só cor. Quanto mais pontos numa mesma área, mais nítida a imagem. Bem de perto, dá para ver os quadradinhos.', 'É como um mosaico de azulejos: cada azulejo tem uma cor só, mas, visto de longe, o conjunto forma um rosto ou uma paisagem.'),
  ('ciencia-pt-virus', 'pt', 'ciencia', 'Vírus', 'Agente infeccioso que só consegue se multiplicar dentro de uma célula', 'Causa gripe e resfriado; antibiótico não funciona contra ele (5 letras)', 'Não é considerado uma célula: é material genético dentro de uma capa de proteína. Sozinho não faz nada; ao entrar numa célula, usa a maquinaria dela para fazer cópias de si mesmo.', 'É como um pen drive com instruções que, ao ser plugado numa fábrica, faz as máquinas pararem o que faziam e passarem a produzir mais pen drives iguais.'),
  ('ciencia-pt-wifi', 'pt', 'ciencia', 'Wifi', 'Rede sem fio que leva a internet do roteador ao celular por ondas de rádio', 'Pedimos a senha dele no café ou na casa dos amigos (4 letras)', 'O roteador transforma os dados em ondas de rádio, invisíveis, e os aparelhos por perto captam e respondem. Paredes grossas e distância enfraquecem o sinal.', 'É como conversar com alguém do outro lado da sala: o som viaja pelo ar sem fio nenhum, mas, se houver paredes demais no caminho, fica difícil ouvir.'),
  ('ciencia-pt-orbita', 'pt', 'ciencia', 'Órbita', 'Caminho curvo que a Lua faz em torno da Terra', 'A da Terra ao redor do Sol leva um ano (6 letras)', 'Um corpo em movimento tende a seguir reto, mas a gravidade de outro corpo o puxa para o lado. O resultado é uma curva fechada: ele cai o tempo todo, mas nunca chega ao chão.', 'É como girar uma bolinha presa num barbante: ela quer fugir em linha reta, o barbante a puxa para o centro, e ela fica dando voltas. No espaço, o barbante é a gravidade.'),
  ('ciencia-pt-vacina', 'pt', 'ciencia', 'Vacina', 'Ensina o sistema imune a reconhecer um micróbio antes de uma infecção real', 'Tomamos no posto de saúde; o Zé Gotinha é o símbolo dela no Brasil', 'Ela apresenta ao corpo uma parte do micróbio, ou uma versão enfraquecida ou inativada dele. As defesas aprendem a reconhecê-lo e guardam memória, reagindo mais rápido se o invasor aparecer.', 'É como um treino de incêndio na escola: ninguém corre perigo, mas todos aprendem o caminho. Quando acontece de verdade, a reação é rápida e organizada.'),
  ('ciencia-pt-bateria', 'pt', 'ciencia', 'Bateria', 'Guarda energia química e a libera como eletricidade quando precisamos', 'A do celular a gente carrega toda noite (7 letras)', 'Dentro dela, reações químicas empurram elétrons de um polo para o outro através do aparelho, gerando corrente. Ao recarregar, a tomada força a reação ao contrário e a energia volta a ficar guardada.', 'É como uma caixa d''água no alto da casa: você enche quando há água sobrando e depois abre a torneira quando precisa, na hora que quiser.'),
  ('ciencia-pt-eletron', 'pt', 'ciencia', 'Elétron', 'Partícula de carga negativa que circula em volta do núcleo do átomo', 'Quando eles andam por um fio, temos corrente elétrica (7 letras)', 'É muito mais leve que prótons e nêutrons. Nos metais, alguns ficam soltos e conseguem se mover; quando são empurrados todos na mesma direção, surge a corrente que acende a lâmpada.', 'É como a água num cano: ela já está lá dentro, e a pilha ou a tomada funciona como a bomba que a empurra para circular.'),
  ('ciencia-pt-celula', 'pt', 'ciencia', 'Célula', 'Menor unidade viva; o corpo humano tem trilhões delas', 'Bactérias são feitas de uma só; tem membrana e, às vezes, núcleo', 'É a menor coisa que consegue viver por conta própria: se alimenta, produz energia e se divide. Uma membrana separa o lado de dentro do lado de fora e controla o que entra e sai.', 'É como um tijolo vivo: casas são feitas de tijolos, e seres vivos, delas. Mas cada uma é também uma minifábrica, com portaria, cozinha e escritório.'),
  ('ciencia-pt-planeta', 'pt', 'ciencia', 'Planeta', 'Corpo grande e arredondado que gira em torno de uma estrela, sem luz própria', 'Marte, Júpiter e a Terra são exemplos (7 letras)', 'Para entrar na lista, precisa orbitar uma estrela, ter massa suficiente para a própria gravidade deixá-lo redondo e ter "limpado" a vizinhança da sua órbita. Por isso Plutão virou planeta-anão.', 'É como um atleta que domina sua raia na pista: corre em volta do centro e é grande o bastante para não dividir a raia com mais ninguém.'),
  ('ciencia-pt-gravidade', 'pt', 'ciencia', 'Gravidade', 'Força de atração entre tudo o que tem massa; nos mantém presos ao chão', 'Newton pensou nela ao ver uma maçã cair (9 letras)', 'Todo objeto com massa puxa os outros, e quanto mais massa e mais perto, mais forte é o puxão. A Terra é tão grande que nos segura no chão; a Lua, menor, puxa menos, e por isso ali se pula mais alto.', 'É como uma cama elástica com uma bola de boliche no meio: ela afunda o tecido, e bolinhas soltas por perto rolam na direção dela.'),
  ('ciencia-pt-telescopio', 'pt', 'ciencia', 'Telescópio', 'Instrumento que junta a luz fraca de objetos distantes para enxergar o céu', 'Galileu apontou um para Júpiter e viu suas luas (10 letras)', 'Usa lentes ou espelhos grandes para coletar muito mais luz do que o olho consegue e concentrá-la num ponto. Assim, estrelas e galáxias fracas demais para a vista aparecem com detalhes.', 'É como um funil enorme na chuva: um copo pega poucas gotas, mas o funil junta a água de uma área grande e enche o copo rapidinho. Só que, em vez de água, junta luz.'),
  ('ciencia-pt-microscopio', 'pt', 'ciencia', 'Microscópio', 'Aparelho de laboratório que amplia o que é pequeno demais para o olho', 'Com ele vemos células e bactérias numa lâmina de vidro (11 letras)', 'Combina lentes para aumentar a imagem centenas de vezes. Foi com ele que descobrimos que seres vivos são feitos de células e que existem micróbios por toda parte.', 'É como uma lupa turbinada: várias lupas trabalhando juntas, uma aumentando a imagem que a outra já aumentou.'),
  ('ciencia-pt-antibiotico', 'pt', 'ciencia', 'Antibiótico', 'Remédio que mata bactérias ou impede que elas se multipliquem', 'A penicilina foi o primeiro; não adianta contra gripe (11 letras)', 'Ataca partes que só as bactérias têm, como a parede da célula delas. Não age contra vírus. Usar sem necessidade ou parar antes da hora ajuda a criar bactérias resistentes.', 'É como uma chave que só abre um tipo de fechadura: funciona contra bactérias, mas não serve para vírus, que têm uma "fechadura" totalmente diferente.'),
  ('ciencia-pt-ecossistema', 'pt', 'ciencia', 'Ecossistema', 'Conjunto de seres vivos de um lugar e o ambiente com que eles interagem', 'Um manguezal, um recife de coral ou a Mata Atlântica (11 letras)', 'Plantas, animais, fungos e micróbios dependem uns dos outros e do solo, da água e do clima. Mexer numa parte, como tirar um predador, pode desequilibrar todo o resto.', 'É como um time de futebol: goleiro, zagueiros e atacantes têm papéis diferentes, e, se um sai sem substituto, o time inteiro sente.'),
  ('ciencia-pt-magnetismo', 'pt', 'ciencia', 'Magnetismo', 'Força invisível que faz o ímã grudar na geladeira e atrair o ferro', 'É por causa dele que a agulha da bússola aponta para o norte (10 letras)', 'Surge do movimento de cargas elétricas, inclusive dentro dos próprios átomos. A Terra tem um campo desse tipo, gerado pelo metal líquido do seu núcleo, e ele orienta as bússolas.', 'É como um campo de futebol invisível em volta do ímã: tudo de ferro que entra nele sente o puxão, e quanto mais perto, mais forte.'),
  ('ciencia-en-atom', 'en', 'ciencia', 'Atom', 'Smallest unit of a chemical element that still behaves like that element', 'Protons and neutrons in the middle, electrons around them (4 letters)', 'Everything around you is built from them. A tiny nucleus of protons and neutrons sits at the center, with electrons around it. The number of protons sets the element: 1 is hydrogen, 8 is oxygen.', 'It''s like a set of building bricks: with only a few kinds of brick you can build almost anything. Water, air and you are different builds made from the same bricks.'),
  ('ciencia-en-cell', 'en', 'ciencia', 'Cell', 'Smallest unit of life; your body has trillions of them', 'Bacteria are made of just one; also a word for a prison room', 'It is the smallest thing that can live on its own: it takes in food, makes energy and divides. A thin membrane separates inside from outside and controls what gets in.', 'Think of a tiny factory with a front gate, a kitchen and an office. Your body is a whole city of these factories, each doing its job.'),
  ('ciencia-en-orbit', 'en', 'ciencia', 'Orbit', 'Curved path the Moon follows around the Earth', 'Earth''s trip around the Sun takes one year (5 letters)', 'A moving object wants to go straight, but the gravity of a bigger body keeps pulling it sideways. The result is a closed loop: it is always falling, yet it never hits the ground.', 'It''s like swinging a ball on a string: the ball wants to fly off straight, the string pulls it inward, and it circles. In space, gravity is the string.'),
  ('ciencia-en-laser', 'en', 'ciencia', 'Laser', 'Narrow, intense beam of light of a single color, used in barcode scanners', 'Cats love chasing its red dot (5 letters)', 'Ordinary bulbs send light in all directions and in many colors. This device makes light of one color whose waves march in step, so the beam stays tight and bright over long distances.', 'It''s like a marching band versus a crowd leaving a stadium: same number of people, but the band moves together in one direction, so it goes much farther.'),
  ('ciencia-en-pixel', 'en', 'ciencia', 'Pixel', 'Tiniest colored dot that makes up a picture on a screen', 'The more of them a screen has, the sharper the image (5 letters)', 'Digital screens and photos are grids of dots, each showing one color. The more dots packed into the same space, the sharper the image. Look very closely and you can see the little squares.', 'It''s like a tile mosaic: each tile is one plain color, but step back and together they form a face or a landscape.'),
  ('ciencia-en-comet', 'en', 'ciencia', 'Comet', 'Icy, dusty body that grows a glowing tail as it nears the Sun', 'Halley''s is famous and returns about every 76 years (5 letters)', 'It is a "dirty snowball" of ice, dust and rock. Close to the Sun, the ice turns to gas and streams away, forming a tail that always points away from the Sun, pushed by sunlight and solar wind.', 'Think of a snowball thrown past a campfire: as it passes the heat it starts steaming, leaving a trail behind it.'),
  ('ciencia-en-vaccine', 'en', 'ciencia', 'Vaccine', 'Trains the immune system to recognize a germ before a real infection', 'Usually given as a shot; the flu one is offered every year', 'It shows the body a harmless piece of a germ, or a weakened or inactivated version. The immune system learns to spot it and keeps a memory, so it reacts faster if the real germ shows up.', 'It''s like a fire drill at school: nobody is in danger, but everyone learns the route, so if a real fire happens the response is quick and calm.'),
  ('ciencia-en-battery', 'en', 'ciencia', 'Battery', 'Stores chemical energy and releases it as electricity on demand', 'Your phone shows its level as a percentage (7 letters)', 'Inside, chemical reactions push electrons from one terminal to the other through your device, creating a current. Charging forces the reaction backward, storing the energy again.', 'It''s like a water tank on the roof: you fill it when water is available, then open the tap whenever you need it.'),
  ('ciencia-en-gravity', 'en', 'ciencia', 'Gravity', 'Pull between all things with mass; it keeps your feet on the ground', 'Newton thought about it after watching an apple fall (7 letters)', 'Every object with mass pulls on every other, and more mass or less distance means a stronger pull. Earth is so massive it holds us down; the Moon pulls less, so you could jump much higher there.', 'Think of a bowling ball on a trampoline: it sinks the fabric, and marbles nearby roll toward it.'),
  ('ciencia-en-protein', 'en', 'ciencia', 'Protein', 'Molecule folded from a chain of amino acids that does most jobs in a cell', 'Found in eggs, beans and meat; muscles are full of it (7 letters)', 'Cells read instructions in DNA and string amino acids together like beads. The chain folds into a precise shape, and that shape decides its job: building muscle, carrying oxygen, speeding up reactions.', 'It''s like folding a long paper strip into origami: the same kind of paper becomes a crane or a boat, and the final shape is what makes it useful.'),
  ('ciencia-en-planet', 'en', 'ciencia', 'Planet', 'Large round body circling a star, with no light of its own', 'Mars, Jupiter and Earth are examples (6 letters)', 'To qualify, it must orbit a star, have enough mass for its own gravity to make it round, and have cleared its orbital neighborhood. That last rule is why Pluto became a dwarf one.', 'It''s like a runner who owns their lane on the track: they circle the center and are big enough that no one else shares the lane.'),
  ('ciencia-en-router', 'en', 'ciencia', 'Router', 'Home box that directs internet data to the right phone or laptop', 'The blinking box that creates your Wi-Fi network (6 letters)', 'Data travels in small packets, each labeled with an address. This device reads the labels and sends each packet to the right device in your home, or out to the internet.', 'Think of a mail sorter at the post office: letters pour in, and the sorter reads each address and drops it in the right bag.'),
  ('ciencia-en-satellite', 'en', 'ciencia', 'Satellite', 'Object circling a planet; GPS and weather forecasts rely on artificial ones', 'The Moon is a natural one of Earth (9 letters)', 'Launched by rockets, these machines circle Earth fast enough that they keep falling around it instead of down. From up there they relay signals, photograph clouds and help your phone find its location.', 'It''s like a lifeguard on a tall chair: from high up you can see the whole beach at once and signal anyone, near or far.'),
  ('ciencia-en-telescope', 'en', 'ciencia', 'Telescope', 'Instrument that gathers faint light to reveal distant stars and galaxies', 'Galileo pointed one at Jupiter and spotted its moons (9 letters)', 'It uses big lenses or mirrors to collect far more light than your eye can and focus it to a point. Objects too dim for the naked eye then appear bright and detailed.', 'It''s like a wide funnel in the rain: a cup alone catches a few drops, but the funnel collects from a big area and fills it fast. It does that with light.'),
  ('ciencia-en-evolution', 'en', 'ciencia', 'Evolution', 'Gradual change of living species over many generations', 'Darwin explained it through natural selection (9 letters)', 'Offspring differ slightly from their parents. Those whose traits help them survive and reproduce pass those traits on more often. Over thousands of generations, small changes add up to new species.', 'Think of a recipe passed down a family: each cook tweaks it a little, the tweaks people love get kept, and after many generations it is a different dish.'),
  ('ciencia-en-bandwidth', 'en', 'ciencia', 'Bandwidth', 'How much data a connection can carry each second', 'Streaming in high definition needs plenty of it (9 letters)', 'It is the capacity of a link, measured in bits per second. More capacity means more data at once, so several people can stream and video call without things freezing.', 'It''s like the number of lanes on a highway: more lanes let more cars travel at the same time without a traffic jam.'),
  ('ciencia-en-antibiotic', 'en', 'ciencia', 'Antibiotic', 'Medicine that kills bacteria or stops them from multiplying', 'Penicillin was the first; useless against a cold (10 letters)', 'It targets parts only bacteria have, such as their cell wall, so it does nothing against viruses. Using it when not needed, or stopping early, helps resistant bacteria spread.', 'It''s like a key cut for one kind of lock: it opens bacteria, but viruses have a totally different lock, so the key is useless there.'),
  ('ciencia-en-ecosystem', 'en', 'ciencia', 'Ecosystem', 'Community of living things plus the environment they interact with', 'A coral reef, a rainforest or a pond (9 letters)', 'Plants, animals, fungi and microbes depend on each other and on soil, water and climate. Changing one part, like removing a predator, can ripple through all the rest.', 'Think of a soccer team: the goalkeeper, defenders and strikers play different roles, and if one leaves with no substitute, the whole team feels it.'),
  ('dinheiro-pt-pix', 'pt', 'dinheiro', 'PIX', 'Pagamento instantâneo brasileiro, que funciona 24 horas, até no domingo', 'Criado pelo Banco Central; usa chave como CPF, e-mail ou celular (3 letras)', 'É o sistema de pagamentos instantâneos criado pelo Banco Central do Brasil. O dinheiro cai na conta de quem recebe em segundos, a qualquer hora, usando uma chave (CPF, celular, e-mail ou aleatória) ou um QR Code.', 'É como entregar uma nota na mão de alguém, só que a distância: não tem fila, não espera o banco abrir e a pessoa recebe na hora.'),
  ('dinheiro-pt-juros', 'pt', 'dinheiro', 'Juros', 'O preço que se paga por usar dinheiro emprestado (ou que se ganha ao emprestar)', 'No cartão de crédito rotativo eles são altíssimos; palavra no plural', 'Quem pega dinheiro emprestado devolve mais do que recebeu: essa diferença são os juros. Do outro lado, quem guarda ou investe recebe juros por deixar outros usarem seu dinheiro por um tempo.', 'É como o aluguel de uma casa, só que o que você aluga é dinheiro: quanto mais tempo fica com ele, mais aluguel paga.'),
  ('dinheiro-pt-acao', 'pt', 'dinheiro', 'Ação', 'Pedacinho de uma empresa que pode ser comprado na Bolsa de Valores', 'Quem tem uma vira sócio da empresa; também significa "atitude"', 'Uma empresa de capital aberto divide sua propriedade em milhões de partes. Quem compra uma delas vira sócio: pode ganhar se a empresa crescer e der lucro, mas também pode perder se ela for mal.', 'É como dividir uma pizza em muitas fatias: quem tem uma fatia é dono de um pedaço da pizza inteira, pequeno, mas de verdade.'),
  ('dinheiro-pt-taxa', 'pt', 'dinheiro', 'Taxa', 'Percentual cobrado, como a Selic definida pelo Banco Central', 'Tarifa ou índice; rima com "faixa" (4 letras)', 'Em economia, é um valor expresso em porcentagem: juros ao mês, tarifa de um serviço, câmbio. A Selic, por exemplo, é a referência de juros do país e influencia o custo dos empréstimos e o rendimento da poupança.', 'Funciona como o termostato da casa: um número pequeno que, quando sobe ou desce, muda o clima de tudo ao redor.'),
  ('dinheiro-pt-lucro', 'pt', 'dinheiro', 'Lucro', 'O que sobra depois de pagar todos os custos de um negócio', 'O contrário de prejuízo (5 letras)', 'É a diferença positiva entre o que um negócio recebe (receita) e tudo o que gasta para funcionar: matéria-prima, salários, aluguel, impostos. Faturar muito não garante sobra se os custos forem maiores.', 'É como vender limonada na rua: o que importa não é quanto entrou no pote, mas o que fica depois de pagar limões, açúcar e copos.'),
  ('dinheiro-pt-renda', 'pt', 'dinheiro', 'Renda', 'Todo o dinheiro que entra por mês: salário, bicos, aluguéis recebidos', 'Também é um tecido delicado de bordado; "fixa" ou "variável"', 'É a soma de tudo o que você recebe num período, como salário, trabalho extra ou aposentadoria. Conhecer a renda real, já sem descontos, é o primeiro passo para planejar gastos.', 'É como a água que entra numa caixa d’água: saber quanto entra por dia é o que permite decidir quanto dá para gastar sem secar.'),
  ('dinheiro-pt-divida', 'pt', 'dinheiro', 'Dívida', 'Valor que alguém deve e precisa pagar no futuro', 'Quem está no vermelho costuma ter uma; sinônimo de débito', 'Surge quando você usa hoje um dinheiro que ainda não tem: empréstimo, parcela, fatura. Nem toda é ruim, mas com juros altos ela cresce rápido. Priorizar quitar as mais caras costuma aliviar o orçamento.', 'É como uma bola de neve rolando morro abaixo: pequena no começo, mas, se ninguém para, os juros fazem ela crescer a cada volta.'),
  ('dinheiro-pt-credito', 'pt', 'dinheiro', 'Crédito', 'Confiança do banco em emprestar para você pagar depois', 'Tem um cartão com esse nome, ao lado do de débito', 'É a possibilidade de comprar ou pegar dinheiro agora e pagar depois. O banco decide quanto oferecer olhando seu histórico de pagamentos. Usar crédito não é ganhar dinheiro: é antecipar uma renda futura.', 'É como a caderneta do mercadinho do bairro: o dono confia que você paga no fim do mês, mas, se atrasar, essa confiança diminui.'),
  ('dinheiro-pt-imposto', 'pt', 'dinheiro', 'Imposto', 'Tributo pago ao governo para financiar escolas, saúde e estradas', 'O de Renda tem declaração anual; ICMS e IPTU são exemplos', 'É o dinheiro que pessoas e empresas pagam obrigatoriamente ao governo. Ele está no salário, no preço do pão e no IPVA do carro, e financia serviços públicos como hospitais, escolas e segurança.', 'É como a vaquinha de um condomínio: cada morador contribui para pagar o porteiro, a limpeza e a manutenção do que todos usam.'),
  ('dinheiro-pt-cambio', 'pt', 'dinheiro', 'Câmbio', 'Troca de uma moeda por outra, como real por dólar', 'Casa de ... é onde se compra moeda para viajar; marcha do carro', 'É a operação de trocar dinheiro de um país pelo de outro, e também o preço dessa troca (a cotação). Quando o dólar sobe, produtos importados e viagens ao exterior ficam mais caros para quem ganha em reais.', 'É como trocar figurinhas: quantas das suas valem uma do amigo depende de quanto cada uma está sendo procurada naquele dia.'),
  ('dinheiro-pt-reserva', 'pt', 'dinheiro', 'Reserva', 'Dinheiro guardado para imprevistos, como perder o emprego ou consertar o carro', 'A "de emergência" costuma cobrir alguns meses de gastos; também é um goleiro do banco', 'É um dinheiro separado só para emergências, guardado em lugar seguro e fácil de sacar. Costuma-se recomendar que cubra de 3 a 6 meses de gastos essenciais, evitando recorrer a empréstimos caros quando algo dá errado.', 'É como o estepe do carro: você torce para não precisar, mas, quando o pneu fura, é ele que te tira do acostamento.'),
  ('dinheiro-pt-inflacao', 'pt', 'dinheiro', 'Inflação', 'Aumento geral dos preços que faz o dinheiro comprar cada vez menos', 'No Brasil, é medida pelo IPCA; o contrário é deflação', 'É quando os preços de modo geral sobem ao longo do tempo. Com a mesma nota de 50 reais você passa a levar menos itens do mercado. Por isso, dinheiro parado sem render perde valor.', 'É como um sorvete no sol: se você deixa o dinheiro parado, ele vai derretendo aos poucos, e no fim compra menos do que comprava.'),
  ('dinheiro-pt-orcamento', 'pt', 'dinheiro', 'Orçamento', 'Plano que compara o que entra e o que sai de dinheiro no mês', 'Pode ser doméstico ou familiar; também é o preço pedido antes de um conserto', 'É anotar quanto você ganha e planejar para onde cada real vai: contas fixas, comida, lazer, guardar. Ver os números no papel ajuda a cortar desperdícios e decidir com calma, em vez de descobrir o rombo no fim do mês.', 'É como o mapa de uma viagem de carro: você sabe quanto combustível tem e planeja as paradas antes de sair, para não ficar sem gasolina no meio da estrada.'),
  ('dinheiro-pt-dividendo', 'pt', 'dinheiro', 'Dividendo', 'Parte do lucro de uma empresa distribuída aos seus acionistas', 'Na conta de dividir, é o número que vai ser repartido', 'Quando uma empresa dá lucro, ela pode repartir uma parte entre os donos de suas ações, em dinheiro. Não é garantido: depende do resultado e da decisão da empresa naquele período.', 'É como ter uma macieira em sociedade com vizinhos: quando ela dá frutos, cada um leva uma parte proporcional ao pedaço que possui.'),
  ('dinheiro-pt-patrimonio', 'pt', 'dinheiro', 'Patrimônio', 'Tudo o que alguém possui (casa, carro, aplicações) menos o que deve', 'Bens e direitos de uma pessoa; também existe o "histórico" de uma cidade', 'É a soma do que você tem (imóveis, veículos, dinheiro investido) descontadas as dívidas. Alguém com carro novo financiado pode ter menos patrimônio do que parece, porque parte do carro ainda é do banco.', 'É como pesar a mochila no fim da trilha: não importa o quanto você carregou no caminho, mas o que realmente sobrou dentro dela.'),
  ('dinheiro-pt-consorcio', 'pt', 'dinheiro', 'Consórcio', 'Grupo que junta parcelas mensais e sorteia quem recebe a carta para comprar', 'Muito usado para comprar carro ou imóvel sem juros, mas com taxa de administração', 'Várias pessoas pagam parcelas a um fundo comum. Todo mês, uma ou mais são contempladas por sorteio ou lance e recebem o valor para comprar o bem. Não há juros, mas há taxa de administração e não se sabe quando você será sorteado.', 'É como uma vaquinha entre amigos em que, a cada mês, um deles leva o total juntado, até que todos tenham recebido a sua vez.'),
  ('dinheiro-pt-previdencia', 'pt', 'dinheiro', 'Previdência', 'Sistema que garante renda na aposentadoria, pública (INSS) ou privada', 'Vem de "prever"; sua contribuição sai todo mês do salário com carteira assinada', 'É uma forma de poupar ao longo da vida de trabalho para ter renda quando parar de trabalhar. A pública, pelo INSS, também cobre doença e invalidez; a privada é um investimento complementar e opcional.', 'É como a formiga da fábula guardando comida no verão: um pouco por vez, durante muito tempo, para não passar aperto no inverno.'),
  ('dinheiro-pt-amortizacao', 'pt', 'dinheiro', 'Amortização', 'Pagamento que reduz o valor principal de uma dívida, não só os juros', 'Adiantar parcelas do financiamento é fazer uma; palavra de 11 letras', 'Cada parcela de um financiamento tem duas partes: juros e uma fatia da dívida original. Essa fatia é a que realmente diminui o que você deve. Pagar valores extras direto nela encurta o prazo e corta juros futuros.', 'É como esvaziar uma piscina furada: só tirar a água que entra (os juros) não adianta, é preciso tirar da água que já estava lá.'),
  ('dinheiro-en-tax', 'en', 'dinheiro', 'Tax', 'Money the government collects to pay for roads, schools and hospitals', 'Income, sales or property ___ (3 letters)', 'A compulsory payment people and businesses make to the government. It may come out of your paycheck, be added to a price at the register, or be charged on property, and it funds public services everyone shares.', 'It''s like a shared household kitty: everyone chips in so the rent, electricity and groceries for the whole home get covered.'),
  ('dinheiro-en-debt', 'en', 'dinheiro', 'Debt', 'Money you owe and must pay back, often with extra on top', 'Being "in the red" means having some; rhymes with "bet"', 'Debt is created when you spend money you do not yet have: a loan, an unpaid card balance, an installment plan. High-interest debt grows quickly, so paying off the most expensive ones first usually frees up the most money.', 'Think of a leaky bucket you must keep refilling: until the hole is patched, part of every paycheck drains out as interest.'),
  ('dinheiro-en-loan', 'en', 'dinheiro', 'Loan', 'A sum of money borrowed from a bank or person, repaid over time', 'Student or car ___; sounds like "lone" (4 letters)', 'A lender gives you a fixed amount now, and you repay it in installments that include interest. The total cost depends on the rate, the length of time and any fees, so comparing offers before signing matters.', 'It''s like borrowing a ladder from a neighbor: handy right away, but you owe it back, and here the neighbor charges a small fee per day.'),
  ('dinheiro-en-bond', 'en', 'dinheiro', 'Bond', 'An IOU sold by governments or companies that pays you interest', 'James ___; also a close emotional connection', 'When you buy one, you are lending money to a government or company. In return they promise to pay interest at regular intervals and give back the original amount on a set date, as long as they stay able to pay.', 'It''s like lending a friend money with a signed note: they agree to pay you a little every month and return the full amount by a certain date.'),
  ('dinheiro-en-asset', 'en', 'dinheiro', 'Asset', 'Anything you own that has value, like a house, savings or a car', 'The opposite of a liability; a valuable team player is one (5 letters)', 'Something you own that is worth money now or could produce money later: cash, a home, investments, tools for a business. Some keep or grow their value; others, like most cars, lose value over time.', 'Think of a fruit tree in your yard: it is worth something just standing there, and some years it also gives you fruit.'),
  ('dinheiro-en-stock', 'en', 'dinheiro', 'Stock', 'A share of ownership in a company, traded on an exchange', 'Also the broth base for soup, or a store''s inventory', 'Buying one makes you a part-owner of a company. Its price rises and falls with how investors view the company''s future, so it can grow your money over years but can also lose value, sometimes sharply.', 'It''s like owning one slice of a pizza: small, but a real piece of the whole pie, worth more if the pizzeria becomes famous.'),
  ('dinheiro-en-budget', 'en', 'dinheiro', 'Budget', 'A plan for how your income will be spent and saved each month', 'A cheap airline is a "___ airline"; to plan spending', 'You list what comes in and decide in advance where each dollar goes: bills, food, fun, savings. Seeing it written down helps catch leaks and makes choices calmer, instead of discovering a shortfall at month''s end.', 'Think of a road-trip plan: you know how much fuel you have and map your stops before leaving, so you don''t run dry halfway there.'),
  ('dinheiro-en-credit', 'en', 'dinheiro', 'Credit', 'Trust that lets you buy now and pay later', 'A plastic card next to the debit card; also thanks in a film''s ending', 'It is the ability to borrow or buy now and pay later. Lenders decide how much to offer by looking at your track record of paying on time. Using it does not add money; it spends future income early.', 'It''s like running a tab at the corner shop: the owner trusts you to settle up at month''s end, and that trust shrinks if you pay late.'),
  ('dinheiro-en-savings', 'en', 'dinheiro', 'Savings', 'Money set aside instead of spent, often kept in a bank account', 'A piggy bank holds them; "life ___"', 'Money you have chosen not to spend so you can use it later, for emergencies or goals. Keeping some in a safe, easy-to-reach account, separate from everyday spending, makes it less tempting to dip into.', 'Think of a squirrel burying acorns in autumn: a few at a time, so there is food waiting when winter comes.'),
  ('dinheiro-en-interest', 'en', 'dinheiro', 'Interest', 'The price of borrowing money, usually a yearly percentage', 'Also means curiosity or attention; "compound ___"', 'Borrowers pay it to lenders for using their money over time. Savers can earn it too. It is usually shown as an annual rate, so a higher rate means a loan costs more, or your savings grow faster.', 'It''s like rent, except what you are renting is money: the longer you keep it, the more rent you pay.'),
  ('dinheiro-en-dividend', 'en', 'dinheiro', 'Dividend', 'A slice of company profits paid out to shareholders', 'In division, the number being divided; "pays ___s" means pays off', 'When a company earns a profit, its board may share part of it with the people who own its shares, usually in cash. It is not guaranteed: it can be raised, cut or skipped depending on how the business is doing.', 'Think of a shared apple tree among neighbors: when it bears fruit, each takes a share in proportion to the part of the tree they own.'),
  ('dinheiro-en-mortgage', 'en', 'dinheiro', 'Mortgage', 'A long-term loan used to buy a home, with the home as security', 'Homeowners often pay one monthly for 15 to 30 years', 'A loan for buying property, repaid over many years. The home itself backs the loan: if payments stop for good, the lender can take it. Small differences in the rate add up to large sums over decades.', 'It''s like moving into a house you are slowly buying brick by brick: each monthly payment makes a few more bricks truly yours.'),
  ('dinheiro-en-inflation', 'en', 'dinheiro', 'Inflation', 'A general rise in prices that makes money buy less over time', 'The opposite of deflation; also what a balloon does when blown up', 'When prices across the economy rise, the same bill buys fewer groceries than before. That is why cash left idle for years slowly loses purchasing power unless it earns at least that much.', 'Think of an ice cream left in the sun: if your money just sits there, it melts a little each day and buys less in the end.'),
  ('dinheiro-en-diversify', 'en', 'dinheiro', 'Diversify', 'To spread money across different investments to lower risk', 'The idea behind "don''t put all your eggs in one basket"', 'Instead of betting everything on one company or one type of investment, you split money among many. If one does badly, the others can soften the blow. It reduces risk but never removes it entirely.', 'It''s like packing a picnic with sandwiches, fruit and snacks: if one gets squashed, you still have plenty to eat.'),
  ('dinheiro-en-liquidity', 'en', 'dinheiro', 'Liquidity', 'How quickly something can be turned into cash without losing value', 'Cash has the most; a house has little. Related to "fluid"', 'Cash in a checking account is highly liquid: you can use it today. A house or a car takes time to sell and you may have to accept a lower price. Emergency money should be kept somewhere very liquid.', 'Think of water versus ice: water pours instantly wherever you need it, while ice has to melt first before you can use it.'),
  ('dinheiro-en-recession', 'en', 'dinheiro', 'Recession', 'A broad economic slowdown, with falling output and rising unemployment', 'A sustained downturn in the economy; worse ones are called depressions', 'A period when the economy shrinks instead of growing: businesses sell less, hire fewer people and some cut jobs. It often lasts months, which is one reason an emergency fund matters.', 'It''s like a whole town catching a cold at once: shops, workers and families all slow down together until things recover.'),
  ('dinheiro-en-collateral', 'en', 'dinheiro', 'Collateral', 'Property pledged to a lender that can be taken if a loan is not repaid', 'A car backs a car loan this way; also "___ damage"', 'Something valuable, like a car or a house, that you offer as a guarantee when borrowing. Because the lender has a fallback, the rate is often lower, but you risk losing the item if you stop paying.', 'Think of leaving your ID at the desk to borrow a basketball at the gym: if you don''t bring the ball back, they keep the ID.'),
  ('dinheiro-en-compounding', 'en', 'dinheiro', 'Compounding', 'Earning returns on your past returns, so growth speeds up over time', 'What happens when interest earns its own interest (11 letters)', 'When the gains your money makes are kept invested, they start earning too. Over many years this snowballs, which is why starting early matters more than starting big. It works against you on debt as well.', 'It''s like a snowball rolling downhill: each turn picks up more snow, and the bigger it gets, the more it picks up on the next turn.'),
  ('bemestar-pt-sono', 'pt', 'bemestar', 'Sono', 'Estado noturno em que o cérebro organiza memórias e o corpo se repara', 'O que falta depois de uma noite em claro (4 letras)', 'Durante o sono o cérebro consolida o que você aprendeu no dia e faz uma espécie de limpeza de resíduos. Adultos costumam precisar de 7 a 9 horas por noite para funcionar bem.', 'É como a equipe de limpeza de uma loja: só entra quando as portas fecham, arruma as prateleiras e deixa tudo pronto para o dia seguinte.'),
  ('bemestar-pt-fibra', 'pt', 'bemestar', 'Fibra', 'Parte dos vegetais que o corpo não digere, mas que ajuda o intestino', 'Abunda no feijão, na aveia e na casca das frutas (5 letras)', 'É a parte de frutas, verduras, grãos e leguminosas que passa pelo estômago sem ser digerida. No intestino, ela dá volume às fezes, alimenta bactérias benéficas e deixa a absorção do açúcar mais lenta.', 'É como uma vassoura que passa pelo intestino: não vira energia, mas varre o caminho e ainda serve de comida para os "moradores" do bairro.'),
  ('bemestar-pt-pausa', 'pt', 'bemestar', 'Pausa', 'Pequena interrupção no trabalho para recuperar a atenção', 'Intervalo, respiro, "dar um tempo" (5 letras)', 'A atenção cansa com o uso contínuo. Levantar, olhar para longe ou caminhar alguns minutos a cada hora ajuda a recuperar o foco e alivia olhos, costas e pernas.', 'É como deixar o motor do carro esfriar numa viagem longa: a parada parece atraso, mas é o que permite chegar inteiro ao destino.'),
  ('bemestar-pt-sol', 'pt', 'bemestar', 'Sol', 'Sua luz da manhã ajusta o relógio interno e ajuda a pele a produzir vitamina D', 'A estrela mais próxima da Terra (3 letras)', 'A luz natural pela manhã avisa ao cérebro que o dia começou, o que ajuda a ter sono na hora certa à noite. Na pele, a radiação UVB permite fabricar vitamina D, mas o excesso queima: o ideal é exposição curta e com cuidado.', 'É como o despertador do corpo inteiro: quando a luz chega, cada órgão confere o horário e sincroniza o seu dia.'),
  ('bemestar-pt-riso', 'pt', 'bemestar', 'Riso', 'Reação contagiante que relaxa músculos e aproxima as pessoas', 'Gargalhada; o "ha-ha-ha" de uma boa piada (4 letras)', 'Rir junto de outras pessoas fortalece laços sociais e costuma trazer uma sensação de alívio logo depois. Ele é contagioso: o cérebro tende a imitar quem ri por perto.', 'É como abrir a janela de uma sala abafada: o ar circula, a tensão diminui e todo mundo ali dentro respira melhor.'),
  ('bemestar-pt-calma', 'pt', 'bemestar', 'Calma', 'Estado de serenidade, oposto da agitação e da pressa', 'Tranquilidade; o que se pede ao nervoso: "tenha ..." (5 letras)', 'É quando o sistema nervoso sai do modo de alerta: o coração desacelera, a respiração fica mais funda e o pensamento clareia. Pode ser treinada com respiração lenta, pausas e boas noites de sono.', 'É como a superfície de um lago sem vento: a água parada deixa ver o fundo com clareza, e a mente serena também enxerga melhor.'),
  ('bemestar-pt-rotina', 'pt', 'bemestar', 'Rotina', 'Sequência de atividades feita mais ou menos nos mesmos horários todo dia', 'Agenda diária que se repete; "sair da ..." (6 letras)', 'Horários regulares para dormir, comer e se mexer ajudam o relógio biológico a se organizar. Além disso, decisões repetidas viram automáticas e sobra energia mental para o que é novo.', 'É como os trilhos de um trem: não tiram a liberdade da viagem, só fazem o caminho exigir menos esforço a cada vez.'),
  ('bemestar-pt-habito', 'pt', 'bemestar', 'Hábito', 'Comportamento repetido tantas vezes que passa a acontecer quase sem pensar', 'Costume; escovar os dentes é um (6 letras)', 'Funciona num ciclo: um gatilho (acordar), uma ação (beber água) e uma recompensa (sentir-se bem). Repetido com frequência, o cérebro grava o atalho e a ação passa a exigir pouca força de vontade.', 'É como uma trilha num gramado: nos primeiros dias quase não aparece, mas de tanto passar ali vira o caminho natural que todos seguem.'),
  ('bemestar-pt-cortisol', 'pt', 'bemestar', 'Cortisol', 'Hormônio liberado no estresse, que também ajuda a despertar de manhã', 'Chamado de "hormônio do estresse" (8 letras)', 'Produzido pelas glândulas suprarrenais, ele sobe naturalmente ao acordar e diante de desafios, liberando energia. O problema é quando fica alto por muito tempo, o que atrapalha o sono e o humor.', 'É como a sirene dos bombeiros: essencial numa emergência, mas, se ficar tocando o dia todo, ninguém descansa e a cidade inteira se esgota.'),
  ('bemestar-pt-dopamina', 'pt', 'bemestar', 'Dopamina', 'Mensageiro do cérebro ligado à motivação e à busca de recompensas', 'Neurotransmissor das notificações e das metas cumpridas (8 letras)', 'É um neurotransmissor que sinaliza "isso vale a pena, faça de novo". Ela age mais na expectativa da recompensa do que no prazer em si, por isso estímulos rápidos e frequentes (como rolar a tela) prendem tanto.', 'É como o cheiro de pão saindo do forno: não é o pão, mas é o que faz você ir até a padaria.'),
  ('bemestar-pt-cochilo', 'pt', 'bemestar', 'Cochilo', 'Soneca curta durante o dia, de preferência com menos de 30 minutos', 'Sesta, "tirar uma pestana" (7 letras)', 'Um descanso de 10 a 20 minutos no início da tarde pode renovar a atenção sem deixar a pessoa grogue. Os longos ou tardios demais podem atrapalhar o sono da noite.', 'É como recarregar o celular por alguns minutos: não enche a bateria, mas garante que ele aguente até a noite.'),
  ('bemestar-pt-gratidao', 'pt', 'bemestar', 'Gratidão', 'Sentimento de reconhecer o que há de bom e quem nos ajudou', 'O que se expressa ao dizer "obrigado" de coração (8 letras)', 'Anotar ou dizer, com regularidade, coisas boas do dia treina a atenção para notar o que funciona, não só os problemas. Estudos associam essa prática a mais bem-estar e relações melhores.', 'É como ajustar a lanterna num quarto escuro: o quarto continua o mesmo, mas você passa a iluminar também os cantos bonitos.'),
  ('bemestar-pt-respiracao', 'pt', 'bemestar', 'Respiração', 'Ato que, feito lento e pela barriga, ajuda a acalmar o corpo', 'Puxar o ar e soltar devagar (10 letras)', 'É a única função automática do corpo que também controlamos à vontade. Soltar o ar devagar, por mais tempo do que se puxa, ativa o sistema nervoso parassimpático, que desacelera o coração.', 'É como o pedal de freio do corpo: você nem sempre controla o trânsito lá fora, mas pode diminuir a velocidade do carro por dentro.'),
  ('bemestar-pt-hidratacao', 'pt', 'bemestar', 'Hidratação', 'Manter o corpo com a quantidade de água de que ele precisa', 'Garrafinha sempre por perto ajuda nela (10 letras)', 'Cerca de 60% do corpo adulto é água, usada para regular a temperatura, transportar nutrientes e lubrificar articulações. Mesmo uma desidratação leve pode trazer cansaço, dor de cabeça e menos concentração.', 'É como o óleo e a água do radiador de um carro: sem eles na medida certa, o motor esquenta e tudo funciona com mais atrito.'),
  ('bemestar-pt-alongamento', 'pt', 'bemestar', 'Alongamento', 'Exercício de estender devagar os músculos para ganhar flexibilidade', 'O gato faz isso ao acordar; esticar o corpo (11 letras)', 'Consiste em levar músculos e articulações até um ponto de leve tensão, sem dor, e segurar alguns segundos. Feito com regularidade, ajuda a manter a amplitude de movimento e alivia a rigidez de quem passa horas sentado.', 'É como desamassar uma camisa que ficou dobrada na gaveta: com um pouco de cuidado, o tecido volta a ter o caimento natural.'),
  ('bemestar-pt-meditacao', 'pt', 'bemestar', 'Meditação', 'Prática de treinar a atenção, por exemplo focando na própria respiração', 'Sentar em silêncio e observar a mente (9 letras)', 'Não é esvaziar a mente, e sim notar quando ela se distrai e trazê-la de volta, várias vezes. Esse "voltar" é o exercício: com prática, a atenção fica mais estável e as emoções, mais fáceis de observar.', 'É como uma academia para a atenção: cada vez que você traz a mente de volta é uma repetição, e o músculo do foco se fortalece.'),
  ('bemestar-pt-circadiano', 'pt', 'bemestar', 'Circadiano', 'Diz-se do ritmo de cerca de 24 horas que regula sono, fome e temperatura', 'Tipo de relógio biológico interno; do latim "cerca de um dia" (10 letras)', 'O corpo tem um relógio interno, acertado principalmente pela luz, que alterna ao longo do dia hormônios, temperatura e disposição. Telas fortes à noite e horários bagunçados podem desregulá-lo.', 'É como o maestro de uma orquestra: diz a cada órgão quando tocar e quando descansar, e a luz do dia é a partitura que ele segue.'),
  ('bemestar-pt-melatonina', 'pt', 'bemestar', 'Melatonina', 'Hormônio liberado no escuro que avisa ao corpo que é hora de dormir', 'O "hormônio da noite", que a luz forte das telas inibe (10 letras)', 'É produzida pela glândula pineal quando a luz diminui. Ela não derruba como um sedativo: funciona como um sinal de horário. Luz intensa à noite atrasa sua liberação e, com ela, o sono.', 'É como as luzes do cinema se apagando antes do filme: não fazem você dormir, mas avisam a todos que a sessão vai começar.'),
  ('bemestar-en-sleep', 'en', 'bemestar', 'Sleep', 'Nightly state in which the brain files memories and the body repairs itself', 'Most adults need 7 to 9 hours of it (5 letters)', 'While you are out at night, the brain consolidates what you learned and clears away metabolic waste. Skimping on it regularly affects mood, focus and appetite.', 'It''s like a library after closing time: the staff reshelve every book borrowed that day so everything can be found tomorrow.'),
  ('bemestar-en-nap', 'en', 'bemestar', 'Nap', 'Short daytime snooze, ideally under half an hour', 'Forty winks; a siesta (3 letters)', 'Ten to twenty minutes of daytime rest can refresh alertness without leaving you groggy. Long or late ones can make it harder to fall asleep at night.', 'It''s like a pit stop in a race: quick, not a full service, but enough to get you back on track with fresh tires.'),
  ('bemestar-en-fiber', 'en', 'bemestar', 'Fiber', 'Plant part your body cannot digest, yet your gut thrives on it', 'Plentiful in beans, oats and apple skins (5 letters)', 'Found in fruit, vegetables, whole grains and legumes, it passes through the stomach undigested. In the gut it adds bulk, feeds helpful bacteria and slows how fast sugar reaches the blood.', 'It''s like a broom moving through your intestines: it does not become fuel, but it sweeps the path clean and feeds the neighbors along the way.'),
  ('bemestar-en-walk', 'en', 'bemestar', 'Walk', 'Simplest exercise of all: one foot in front of the other', 'A stroll around the block (4 letters)', 'Moving at a brisk pace raises the heart rate gently, helps blood sugar after meals and lifts mood. Even short bouts spread through the day add up.', 'It''s like stirring a pot so nothing sticks: a little regular movement keeps everything in the body flowing smoothly.'),
  ('bemestar-en-habit', 'en', 'bemestar', 'Habit', 'Behavior repeated so often it runs almost on autopilot', 'Brushing your teeth is one; a routine custom (5 letters)', 'It runs on a loop: a cue (waking up), an action (drinking water) and a reward (feeling good). Repeat it enough and the brain stores a shortcut, so it needs little willpower.', 'It''s like a path across a lawn: faint at first, but after enough footsteps it becomes the natural way everyone goes.'),
  ('bemestar-en-rest', 'en', 'bemestar', 'Rest', 'Recovery time that lets muscles rebuild between workouts', 'Put your feet up; take a breather (4 letters)', 'Muscles do not get stronger during exercise but in the recovery afterwards, when tiny strains are repaired. Skipping recovery days raises the risk of fatigue and injury.', 'Think of bread dough: kneading builds it up, but it only rises when you leave it alone for a while.'),
  ('bemestar-en-routine', 'en', 'bemestar', 'Routine', 'Set sequence of daily activities done at roughly the same times', 'Daily schedule; "stuck in a ..." (7 letters)', 'Regular times for sleeping, eating and moving help the body clock stay in sync. Repeated choices also become automatic, freeing mental energy for new things.', 'It''s like train tracks: they do not limit the journey, they just make each trip take less effort.'),
  ('bemestar-en-posture', 'en', 'bemestar', 'Posture', 'How you hold your body while sitting or standing', 'Parents say "sit up straight" to fix it (7 letters)', 'No single position is perfect for hours. What helps most is changing position often, keeping screens near eye level and letting the spine keep its natural curves.', 'It''s like stacking blocks: when they are balanced, the tower stands with little effort; lean them and every block has to strain.'),
  ('bemestar-en-stretch', 'en', 'bemestar', 'Stretch', 'Slowly lengthen a muscle to ease stiffness', 'What a cat does after waking up (7 letters)', 'Holding a muscle at gentle tension, never pain, for several seconds helps maintain range of motion. It is especially welcome after long periods of sitting.', 'It''s like ironing a shirt that sat folded in a drawer: a little care and the fabric hangs naturally again.'),
  ('bemestar-en-cortisol', 'en', 'bemestar', 'Cortisol', 'Hormone that rises under pressure and also helps you wake up', 'Nicknamed "the stress hormone" (8 letters)', 'Made by the adrenal glands, it naturally peaks in the morning and during challenges, freeing up energy. Trouble starts when it stays high for long stretches, disturbing sleep and mood.', 'It''s like a fire alarm: vital in an emergency, but if it never stops ringing, nobody in the building can rest.'),
  ('bemestar-en-dopamine', 'en', 'bemestar', 'Dopamine', 'Brain messenger tied to motivation and chasing rewards', 'Neurotransmitter behind the pull of phone notifications (8 letters)', 'This neurotransmitter signals "this is worth it, do it again". It is driven more by the anticipation of a reward than the pleasure itself, which is why quick, frequent hits like scrolling are so gripping.', 'It''s like the smell of fresh bread from a bakery: it is not the bread, but it is what makes you walk inside.'),
  ('bemestar-en-sunlight', 'en', 'bemestar', 'Sunlight', 'Morning dose of it sets your body clock; skin uses it to make vitamin D', 'Rays from our nearest star (8 letters)', 'Bright natural light early in the day tells the brain the day has begun, which helps you feel sleepy at the right time at night. Too much on bare skin burns, so short, sensible exposure is best.', 'It''s like the conductor''s first downbeat: once it arrives, every organ checks the time and plays in rhythm.'),
  ('bemestar-en-hydration', 'en', 'bemestar', 'Hydration', 'Keeping your body supplied with the water it needs', 'A refillable bottle on your desk helps with it (9 letters)', 'About 60% of an adult body is water, used to control temperature, carry nutrients and cushion joints. Even mild shortfalls can bring tiredness, headaches and poorer concentration.', 'It''s like coolant in a car engine: with the right amount, everything runs smoothly; let it drop and things overheat.'),
  ('bemestar-en-breathing', 'en', 'bemestar', 'Breathing', 'Done slowly from the belly, it can calm a racing heart', 'Inhaling and exhaling (9 letters)', 'It is the one automatic body function you can also steer at will. Making each exhale longer than the inhale activates the parasympathetic nervous system, the body''s "rest and digest" mode.', 'It''s like a brake pedal for your body: you cannot control the traffic outside, but you can slow the car down from within.'),
  ('bemestar-en-gratitude', 'en', 'bemestar', 'Gratitude', 'Feeling of appreciating what is good and who has helped you', 'What a heartfelt "thank you" expresses (9 letters)', 'Regularly noting good things from your day trains attention to spot what works, not just the problems. Studies link the practice to greater well-being and stronger relationships.', 'It''s like turning a flashlight in a dark room: the room is the same, but now you also light up its lovely corners.'),
  ('bemestar-en-melatonin', 'en', 'bemestar', 'Melatonin', 'Hormone released in darkness that tells the body it is bedtime', 'The "hormone of night", held back by bright screens (9 letters)', 'The pineal gland releases it as light fades. It does not knock you out like a sedative; it works as a timing signal. Bright light in the evening delays it, and your sleep with it.', 'It''s like the cinema lights dimming before a film: they do not put you to sleep, but they tell everyone the show is about to start.'),
  ('bemestar-en-resilience', 'en', 'bemestar', 'Resilience', 'Ability to adapt and bounce back after hard times', 'Emotional toughness; grit to recover (10 letters)', 'It is not about never struggling but about recovering and adapting. It grows with supportive relationships, good sleep, a sense of purpose and seeing setbacks as something you can work through.', 'It''s like a bamboo stalk in a storm: it bends with the wind instead of snapping, and stands up again when the gust passes.'),
  ('bemestar-en-mindfulness', 'en', 'bemestar', 'Mindfulness', 'Paying full attention to the present moment, without judging it', 'Popular meditation practice of noticing the here and now (11 letters)', 'It means noticing thoughts, feelings and sensations as they happen, without labeling them good or bad. Practiced regularly, it helps people step back from autopilot reactions.', 'It''s like watching cars pass from the sidewalk instead of chasing each one: you see your thoughts go by without being dragged along.')
